package com.gamehubstore.notification_mscv.services;
import com.gamehubstore.notification_mscv.client.UserClient;import com.gamehubstore.notification_mscv.models.Notification;import com.gamehubstore.notification_mscv.repositories.NotificationRepository;import org.junit.jupiter.api.Test;import java.util.Map;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class NotificationServiceTest {@Test void newNotificationIsUnreadAndUserIsChecked(){NotificationRepository repo=mock(NotificationRepository.class);UserClient users=mock(UserClient.class);NotificationService service=new NotificationService(repo,users);when(users.findUser(6L)).thenReturn(Map.of("userId",6));when(repo.save(any())).thenAnswer(a->a.getArgument(0));Notification n=new Notification();n.setUserId(6L);n.setType("ORDEN");n.setMessage("Confirmada");assertFalse(service.create(n).isRead());verify(users).findUser(6L);}
@Test void readNotificationCannotBecomeUnread(){NotificationRepository repo=mock(NotificationRepository.class);NotificationService service=new NotificationService(repo,mock(UserClient.class));Notification n=new Notification();n.setRead(true);when(repo.findById(1L)).thenReturn(Optional.of(n));assertSame(n,service.markRead(1L));verify(repo,never()).save(any());}}
